const neighboursOf = ([x, y]: Cell): Cell[] =>
  NEIGHBOUR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);

export function nextGeneration(cells: Cell[]): Cell[] {
  const isAlive = ([x, y]: Cell): boolean =>
    cells.some(([cx, cy]) => cx === x && cy === y);

  const countLiveNeighbours = (cell: Cell): number =>
    neighboursOf(cell).filter(isAlive).length;

  const survives = (cell: Cell): boolean =>
    [2, 3].includes(countLiveNeighbours(cell));

  const isBorn = (cell: Cell): boolean =>
    !isAlive(cell) && countLiveNeighbours(cell) === 3;

  const deadNeighbours = cells.flatMap(neighboursOf).filter((cell) => !isAlive(cell));
  const births = deadNeighbours.filter(isBorn);
  const uniqueBirths = births.filter(
    ([x, y], index) => births.findIndex(([bx, by]) => bx === x && by === y) === index,
  );

  return [...cells.filter(survives), ...uniqueBirths];
}

